const toSnake = (s) => s.replace(/([A-Z])/g, "_$1").toLowerCase();
const toDbType = (singular) => `DbTlo${singular}`;
const toSummary = (singular) => `${singular}Summary`;
const toInput = (singular) => `Create${singular}Input`;
const toSchema = (tab) => `${tab.replace(/s$/, "")}FormSchema`.replace(/ContextFormSchema/, "tenantContextFormSchema").replace(/RecordFormSchema/, "lifecycleRecordFormSchema").replace(/TransitionFormSchema/, "lifecycleTransitionFormSchema").replace(/EventFormSchema/, "lifecycleEventFormSchema").replace(/RequestFormSchema/, "reactivationRequestFormSchema").replace(/SettingFormSchema/, "environmentSettingFormSchema").replace(/ManagementFormSchema/, "storageManagementFormSchema").replace(/ControlFormSchema/, "operationsControlFormSchema").replace(/FlowFormSchema/, "onboardingFlowFormSchema").replace(/ProgressFormSchema/, "onboardingProgressFormSchema").replace(/ValidationFormSchema/, "onboardingValidationFormSchema").replace(/ChecklistFormSchema/, "goLiveChecklistFormSchema").replace(/ModuleFormSchema/, "marketplaceModuleFormSchema").replace(/InstallationFormSchema/, "moduleInstallationFormSchema").replace(/DependencyFormSchema/, "moduleDependencyFormSchema").replace(/CompatibilityFormSchema/, "moduleCompatibilityFormSchema").replace(/PackFormSchema/, "industryPackFormSchema").replace(/packInstallationFormSchema/, "packInstallationFormSchema").replace(/VersionFormSchema/, "packVersionFormSchema").replace(/ExportFormSchema/, "packExportFormSchema").replace(/SnapshotFormSchema/, "healthSnapshotFormSchema").replace(/DimensionFormSchema/, "healthDimensionFormSchema").replace(/RiskFormSchema/, "healthRiskFormSchema").replace(/ScoreFormSchema/, "healthScoreFormSchema").replace(/PlanFormSchema/, "successPlanFormSchema").replace(/ReviewFormSchema/, "quarterlyReviewFormSchema").replace(/renewalPlanFormSchema/, "renewalPlanFormSchema").replace(/MilestoneFormSchema/, "customerMilestoneFormSchema").replace(/MetricFormSchema/, "commercialMetricFormSchema").replace(/growthSnapshotFormSchema/, "growthSnapshotFormSchema").replace(/OpportunityFormSchema/, "expansionOpportunityFormSchema");

function fixSchema(tab) {
    const map = {
        tenantContexts: "tenantContextFormSchema",
        lifecycleRecords: "lifecycleRecordFormSchema",
        lifecycleTransitions: "lifecycleTransitionFormSchema",
        lifecycleEvents: "lifecycleEventFormSchema",
        reactivationRequests: "reactivationRequestFormSchema",
        environmentSettings: "environmentSettingFormSchema",
        storageManagement: "storageManagementFormSchema",
        operationsControls: "operationsControlFormSchema",
        onboardingFlows: "onboardingFlowFormSchema",
        onboardingProgress: "onboardingProgressFormSchema",
        onboardingValidations: "onboardingValidationFormSchema",
        goLiveChecklists: "goLiveChecklistFormSchema",
        marketplaceModules: "marketplaceModuleFormSchema",
        moduleInstallations: "moduleInstallationFormSchema",
        moduleDependencies: "moduleDependencyFormSchema",
        moduleCompatibility: "moduleCompatibilityFormSchema",
        industryPacks: "industryPackFormSchema",
        packInstallations: "packInstallationFormSchema",
        packVersions: "packVersionFormSchema",
        packExports: "packExportFormSchema",
        healthSnapshots: "healthSnapshotFormSchema",
        healthDimensions: "healthDimensionFormSchema",
        healthRisks: "healthRiskFormSchema",
        healthScores: "healthScoreFormSchema",
        successPlans: "successPlanFormSchema",
        quarterlyReviews: "quarterlyReviewFormSchema",
        renewalPlans: "renewalPlanFormSchema",
        customerMilestones: "customerMilestoneFormSchema",
        commercialMetrics: "commercialMetricFormSchema",
        growthSnapshots: "growthSnapshotFormSchema",
        expansionOpportunities: "expansionOpportunityFormSchema",
        workspaces: "workspaceFormSchema",
    };
    return map[tab] ?? `${tab.slice(0, -1)}FormSchema`;
}

function fixFormValues(tab) {
    return fixSchema(tab).replace("FormSchema", "FormValues");
}

for (const e of entities) {
    e.schema = fixSchema(e.tab);
    e.form = fixFormValues(e.tab);
    e.summary = toSummary(e.singular);
    e.input = toInput(e.singular);
    e.dbType = toDbType(e.singular);
    e.repo = `Tlo${e.singular}Repository`;
    e.map = `map${e.singular}Summary`;
    e.build = `build${e.singular}Payload`;
    e.get = `get${e.singular}s`;
    e.create = `create${e.singular}`;
    e.update = `update${e.singular}`;
    e.delete = `delete${e.singular}`;
}

function genDbTypes() {
    const blocks = entities.map((e) => {
        const cols = e.orgScoped
            ? `id: string;\n    organization_id: string;\n    ${toSnake(e.keyField)}: string;\n    status: string;\n    created_at: string;\n    updated_at: string;`
            : e.tab === "lifecycleEvents"
              ? `id: string;\n    organization_id: string;\n    tenant_context_id: string;\n    ${toSnake(e.keyField)}: string;\n    status: string;\n    created_at: string;`
              : `id: string;\n    organization_id: string;\n    tenant_context_id: string;\n    ${toSnake(e.keyField)}: string;\n    status: string;\n    created_at: string;\n    updated_at: string;`;
        return `export interface ${e.dbType} {\n    ${cols}\n}`;
    });
    blocks.push(`export interface DbTloAuditLog {\n    id: string;\n    organization_id: string;\n    entity_type: string;\n    entity_id?: string | null;\n    action: string;\n    summary: string;\n    metadata: Record<string, unknown>;\n    performed_by?: string | null;\n    security_level: string;\n    created_at: string;\n}`);
    return blocks.join("\n\n") + "\n";
}

function genRepos() {
    const imports = entities.map((e) => e.dbType).concat(["DbTloAuditLog"]).join(",\n    ");
    const classes = entities.map((e) => `export class ${e.repo} extends OrgTloRepository<${e.dbType}> { protected table = "${e.table}"; }`).join("\n");
    return `import type {\n    ${imports},\n} from "@/src/modules/database/types/tlo-platform";\nimport { getRepositoryClient, mapRepositoryError } from "@/src/modules/database/lib/repository-client";\nimport { BaseRepository, type RepositoryQuery } from "@/src/modules/database/repositories/base-repository";\n\nabstract class OrgTloRepository<T> extends BaseRepository<T> {\n    async listByOrganization(organizationId: string, query: RepositoryQuery = {}): Promise<T[]> {\n        const client = getRepositoryClient();\n        if (!client) return [];\n        const normalized = this.buildQuery(query);\n        const { data, error } = await client.from(this.table).select("*").eq("organization_id", organizationId).order(normalized.orderBy, { ascending: normalized.orderDirection === "asc" }).range(normalized.offset, normalized.offset + normalized.limit - 1);\n        mapRepositoryError(error, \`Failed to list \${this.table}\`);\n        return (data ?? []) as T[];\n    }\n\n    async getById(id: string): Promise<T | null> {\n        const client = getRepositoryClient();\n        if (!client) return null;\n        const { data, error } = await client.from(this.table).select("*").eq("id", id).maybeSingle();\n        mapRepositoryError(error, \`Failed to get \${this.table}\`);\n        return (data as T | null) ?? null;\n    }\n\n    async create(input: Record<string, unknown>): Promise<T | null> {\n        const client = getRepositoryClient();\n        if (!client) return null;\n        const { data, error } = await client.from(this.table).insert(input).select("*").maybeSingle();\n        mapRepositoryError(error, \`Failed to create \${this.table}\`);\n        return (data as T | null) ?? null;\n    }\n\n    async update(id: string, input: Record<string, unknown>): Promise<T | null> {\n        const client = getRepositoryClient();\n        if (!client) return null;\n        const { data, error } = await client.from(this.table).update(input).eq("id", id).select("*").maybeSingle();\n        mapRepositoryError(error, \`Failed to update \${this.table}\`);\n        return (data as T | null) ?? null;\n    }\n\n    async delete(id: string): Promise<boolean> {\n        const client = getRepositoryClient();\n        if (!client) return false;\n        const { error } = await client.from(this.table).delete().eq("id", id);\n        mapRepositoryError(error, \`Failed to delete \${this.table}\`);\n        return !error;\n    }\n}\n\n${classes}\nexport class TloAuditLogRepository extends OrgTloRepository<DbTloAuditLog> { protected table = "tlo_audit_logs"; }\n`;
}

function genTypes() {
    const blocks = [`export interface TloDashboardStats {\n    totalTenantContexts: number;\n    activeTenantContexts: number;\n    lifecycleRecordCount: number;\n    openReactivationCount: number;\n    onboardingInProgressCount: number;\n    marketplaceModuleCount: number;\n    industryPackCount: number;\n    avgHealthScore: number;\n    openExpansionCount: number;\n    auditCount: number;\n}`, `export interface TloPipelineInfo {\n    stages: Array<{ key: string; label: string }>;\n    currentStage: string;\n    nextStage: string;\n    previousStage: string;\n}`, `export interface AuditEntry {\n    id: string;\n    entityType: string;\n    entityId?: string | null;\n    action: string;\n    summary: string;\n    securityLevel: string;\n    createdAt: string;\n}`];
    for (const e of entities) {
        blocks.push(`export interface ${e.summary} {\n    id: string;\n    ${e.maps ? "tenantContextName: string;\n    " : ""}${e.keyField}: string;\n    ${e.titleKey !== e.keyField ? `${e.titleKey}: string;\n    ` : ""}status: string;\n}`);
        blocks.push(`export interface ${e.input} {\n    ${e.orgScoped ? "" : "tenantContextId: string;\n    "}${e.keyField}?: string;\n    ${e.fields.filter((f) => f.name !== e.keyField).map((f) => `${f.name}${f.number ? "?: number" : "?: string"};`).join("\n    ")}\n}`);
    }
    blocks.push(`export interface TloSdkProvisionTenantInput { contextKey: string; companyName: string; lifecycleStage?: string; }\nexport interface TloSdkProvisionTenantResult { contextId: string; contextKey: string; recordId: string; aiTaskId?: string | null; }\nexport interface TloSdkTransitionLifecycleInput { tenantContextId: string; transitionKey: string; fromStage: string; toStage: string; reason?: string; }\nexport interface TloSdkTransitionLifecycleResult { transitionId: string; transitionKey: string; toStage: string; status: string; }\nexport interface TloSdkInstallIndustryPackInput { tenantContextId: string; packKey: string; packName: string; industry?: string; }\nexport interface TloSdkInstallIndustryPackResult { packId: string; packKey: string; installationId: string; status: string; }`);
    return blocks.join("\n\n") + "\n";
}

function genMappersHeader() {
    const dbImports = entities.map((e) => e.dbType).concat(["DbTloAuditLog", "DbTloTenantContext"]).filter((v, i, a) => a.indexOf(v) === i);
    const typeImports = entities.flatMap((e) => [e.input, e.summary]).concat(["TloDashboardStats", "TloPipelineInfo", "AuditEntry", "CreateTenantContextInput"]);
    return { dbImports, typeImports };
}

function genMappers() {
    const { dbImports, typeImports } = genMappersHeader();
    const mapFns = entities.map((e) => {
        const extra = e.tab === "tenantContexts"
            ? `companyName: (record as DbTloTenantContext).company_name,\n    lifecycleStage: (record as DbTloTenantContext).lifecycle_stage,`
            : e.titleKey !== e.keyField ? `${e.titleKey}: String((record as Record<string, unknown>).${toSnake(e.titleKey.replace(/([A-Z])/g, "_$1").toLowerCase().replace(/^_/, ""))} ?? (record as Record<string, unknown>).${toSnake(e.keyField)} ?? ""),` : "";
        const mapBody = e.maps
            ? `${e.map} = (record: ${e.dbType}, maps: LookupMaps): ${e.summary} => ({\n    id: record.id,\n    tenantContextName: tenantContextName(maps, record.tenant_context_id) ?? "",\n    ${e.keyField}: String((record as Record<string, unknown>).${toSnake(e.keyField)} ?? ""),\n    ${extra}\n    status: record.status,\n});`
            : e.tab === "tenantContexts"
              ? `${e.map} = (record: DbTloTenantContext): ${e.summary} => ({\n    id: record.id,\n    contextKey: record.context_key,\n    companyName: record.company_name,\n    lifecycleStage: record.lifecycle_stage,\n    status: record.status,\n});`
              : `${e.map} = (record: ${e.dbType}): ${e.summary} => ({\n    id: record.id,\n    ${e.keyField}: String((record as Record<string, unknown>).${toSnake(e.keyField)} ?? ""),\n    ${extra}\n    status: record.status,\n});`;
        return mapBody;
    });
    const buildFns = entities.map((e) => {
        const payloadFields = e.orgScoped
            ? [`${toSnake(e.keyField)}: input.${e.keyField} ?? ""`, ...e.fields.filter((f) => f.name !== e.keyField).map((f) => `${toSnake(f.name)}: input.${f.name} ?? ${f.number ? "0" : '""'}`)]
            : [`tenant_context_id: input.tenantContextId`, `${toSnake(e.keyField)}: input.${e.keyField} ?? ""`, ...e.fields.filter((f) => f.name !== e.keyField).map((f) => `${toSnake(f.name)}: input.${f.name} ?? ${f.number ? "0" : '""'}`)];
        return `${e.build} = (organizationId: string, input: ${e.input}) => ({\n    organization_id: organizationId,\n    ${payloadFields.join(",\n    ")},\n});`;
    });
    return `import type {\n    ${dbImports.join(",\n    ")},\n} from "@/src/modules/database/types/tlo-platform";\nimport type {\n    ${[...new Set(typeImports)].join(",\n    ")},\n} from "@/src/modules/tenant-lifecycle-ops/types";\n\ntype LookupMaps = { tenantContexts: Map<string, DbTloTenantContext> };\n\nexport const buildTenantContextLookupMaps = (tenantContexts: DbTloTenantContext[]): LookupMaps => ({\n    tenantContexts: new Map(tenantContexts.map((item) => [item.id, item])),\n});\n\nconst tenantContextName = (maps: LookupMaps, id?: string | null) => (id ? maps.tenantContexts.get(id)?.company_name ?? null : null);\n\nexport const mapAuditEntry = (record: DbTloAuditLog): AuditEntry => ({\n    id: record.id,\n    entityType: record.entity_type,\n    entityId: record.entity_id,\n    action: record.action,\n    summary: record.summary,\n    securityLevel: record.security_level,\n    createdAt: record.created_at,\n});\n\nexport const buildTloAuditPayload = (organizationId: string, entityType: string, action: string, summary: string, entityId?: string, securityLevel = "standard") => ({\n    organization_id: organizationId,\n    entity_type: entityType,\n    entity_id: entityId ?? null,\n    action,\n    summary,\n    security_level: securityLevel,\n});\n\nexport const buildTloDashboardStats = (input: {\n    tenantContexts: TenantContextSummary[];\n    lifecycleRecords: unknown[];\n    reactivationRequests: { status: string }[];\n    onboardingProgress: { status: string }[];\n    marketplaceModules: unknown[];\n    industryPacks: unknown[];\n    healthSnapshots: { overallScore: number }[];\n    expansionOpportunities: { status: string }[];\n    auditLogs: unknown[];\n}): TloDashboardStats => ({\n    totalTenantContexts: input.tenantContexts.length,\n    activeTenantContexts: input.tenantContexts.filter((t) => t.status === "active").length,\n    lifecycleRecordCount: input.lifecycleRecords.length,\n    openReactivationCount: input.reactivationRequests.filter((r) => r.status === "pending").length,\n    onboardingInProgressCount: input.onboardingProgress.filter((p) => p.status === "in_progress").length,\n    marketplaceModuleCount: input.marketplaceModules.length,\n    industryPackCount: input.industryPacks.length,\n    avgHealthScore: input.healthSnapshots.length ? input.healthSnapshots.reduce((s, h) => s + h.overallScore, 0) / input.healthSnapshots.length : 0,\n    openExpansionCount: input.expansionOpportunities.filter((o) => o.status === "open").length,\n    auditCount: input.auditLogs.length,\n});\n\nexport const buildTloPipelineInfo = (): TloPipelineInfo => ({\n    stages: [\n        { key: "lead", label: "Lead" },\n        { key: "trial", label: "Trial" },\n        { key: "onboarding", label: "Onboarding" },\n        { key: "active", label: "Active" },\n        { key: "expansion", label: "Expansion" },\n        { key: "renewal", label: "Renewal" },\n    ],\n    currentStage: "onboarding",\n    nextStage: "active",\n    previousStage: "trial",\n});\n\nexport const ${mapFns.join("\n\nexport const ")}\n\nexport const ${buildFns.join("\n\nexport const ")}\n`;
}

function genConstants() {
    const tabs = ["overview", ...entities.map((e) => e.tab), "audit", "api"];
    return `export const TLO_TABS = {\n${tabs.map((t) => `    ${t}: "${t}",`).join("\n")}\n} as const;\n\nexport const LIFECYCLE_STAGE_OPTIONS = [\n    { value: "lead", label: "Lead" },\n    { value: "trial", label: "Trial" },\n    { value: "onboarding", label: "Onboarding" },\n    { value: "active", label: "Active" },\n    { value: "expansion", label: "Expansion" },\n    { value: "renewal", label: "Renewal" },\n    { value: "at_risk", label: "At Risk" },\n    { value: "churned", label: "Churned" },\n    { value: "cancelled", label: "Cancelled" },\n] as const;\n\nexport const INDUSTRY_PACK_OPTIONS = [\n    { value: "healthcare", label: "Healthcare" },\n    { value: "financial_services", label: "Financial Services" },\n    { value: "retail", label: "Retail" },\n    { value: "manufacturing", label: "Manufacturing" },\n    { value: "technology", label: "Technology" },\n    { value: "professional_services", label: "Professional Services" },\n    { value: "education", label: "Education" },\n    { value: "government", label: "Government" },\n] as const;\n\nexport const SEVERITY_OPTIONS = [\n    { value: "low", label: "Low" },\n    { value: "medium", label: "Medium" },\n    { value: "high", label: "High" },\n    { value: "critical", label: "Critical" },\n] as const;\n\nexport const TLO_STATUS_OPTIONS = [\n    { value: "draft", label: "Draft" },\n    { value: "active", label: "Active" },\n    { value: "pending", label: "Pending" },\n    { value: "inactive", label: "Inactive" },\n    { value: "in_progress", label: "In Progress" },\n    { value: "open", label: "Open" },\n    { value: "completed", label: "Completed" },\n] as const;\n\nexport const TLO_PERMISSIONS = ["tlo.view", "tlo.manage", "tlo.approve", "tlo.admin"] as const;\n\nexport const TLO_THEME = {\n    primary: "emerald-600",\n    primaryHover: "emerald-500",\n    ring: "emerald-500/20",\n    text: "text-emerald-600",\n    textDark: "dark:text-emerald-400",\n    bg: "bg-emerald-600",\n    bgHover: "hover:bg-emerald-500",\n} as const;\n`;
}

function genSchemas() {
    return entities.map((e) => {
        const fields = e.orgScoped
            ? e.fields.map((f) => `    ${f.name}: ${f.number ? "z.number().optional()" : f.name.includes("Key") || f.name === "companyName" ? "z.string().min(2)" : "z.string().min(2).optional()"},`).join("\n")
            : [`    tenantContextId: z.string().min(1),`, ...e.fields.map((f) => `    ${f.name}: ${f.number ? "z.number().optional()" : f.name.includes("Key") ? "z.string().min(2)" : "z.string().min(2).optional()"},`)].join("\n");
        return `export const ${e.schema} = z.object({\n${fields}\n});`;
    }).join("\n\n") + "\n\n" + entities.map((e) => `export type ${e.form} = z.infer<typeof ${e.schema}>;`).join("\n") + "\n";
}

function genService() {
    const mapperImports = [...new Set(entities.flatMap((e) => [e.map, e.build]))].concat(["buildTloAuditPayload", "buildTloDashboardStats", "buildTloPipelineInfo", "buildTenantContextLookupMaps", "mapAuditEntry"]).sort();
    const typeImports = [...new Set(entities.flatMap((e) => [e.input, e.summary]))].concat(["AuditEntry", "TloDashboardStats", "TloPipelineInfo", "TloSdkProvisionTenantInput", "TloSdkProvisionTenantResult", "TloSdkTransitionLifecycleInput", "TloSdkTransitionLifecycleResult", "TloSdkInstallIndustryPackInput", "TloSdkInstallIndustryPackResult"]).sort();
    const methods = entities.map((e) => {
        const getBody = e.maps
            ? `const maps = await this.getMaps(context.organizationId);\n        return (await databaseService.${e.db}.listByOrganization(context.organizationId)).map((r) => ${e.map}(r, maps));`
            : `return (await databaseService.${e.db}.listByOrganization(context.organizationId)).map(${e.map});`;
        const createReturn = e.maps ? `\n        const maps = await this.getMaps(context.organizationId);\n        return ${e.map}(created, maps);` : `\n        return ${e.map}(created);`;
        const updateReturn = e.maps ? `\n        const maps = await this.getMaps(context.organizationId);\n        return ${e.map}(updated, maps);` : `\n        return ${e.map}(updated);`;
        const patchLines = e.fields.map((f) => `if (input.${f.name} !== undefined) patch.${toSnake(f.name)} = input.${f.name};`).join("\n        ");
        return `    async ${e.get}(authUserId: string, email: string, fullName?: string | null): Promise<${e.summary}[]> {\n        const context = await this.getContext(authUserId, email, fullName);\n        if (!context) return [];\n        ${getBody}\n    }\n\n    async ${e.create}(authUserId: string, email: string, input: ${e.input}, fullName?: string | null): Promise<${e.summary}> {\n        const context = await this.getContext(authUserId, email, fullName);\n        if (!context) throw new Error("Unable to resolve organization context");\n        const created = await databaseService.${e.db}.create(${e.build}(context.organizationId, input));\n        if (!created) throw new Error("Failed to create ${e.tab}");\n        await databaseService.tloAuditLogs.create(buildTloAuditPayload(context.organizationId, "${e.audit}", "create", \`${e.singular} created\`, created.id));${createReturn}\n    }\n\n    async ${e.update}(authUserId: string, email: string, id: string, input: Partial<${e.input}>, fullName?: string | null): Promise<${e.summary}> {\n        const context = await this.getContext(authUserId, email, fullName);\n        if (!context) throw new Error("Unable to resolve organization context");\n        const patch: Record<string, unknown> = {};\n        ${patchLines}\n        const updated = await databaseService.${e.db}.update(id, patch);\n        if (!updated) throw new Error("Failed to update ${e.tab}");\n        await databaseService.tloAuditLogs.create(buildTloAuditPayload(context.organizationId, "${e.audit}", "update", \`${e.singular} updated\`, updated.id));${updateReturn}\n    }\n\n    async ${e.delete}(authUserId: string, email: string, id: string, fullName?: string | null): Promise<boolean> {\n        const context = await this.getContext(authUserId, email, fullName);\n        if (!context) throw new Error("Unable to resolve organization context");\n        const ok = await databaseService.${e.db}.delete(id);\n        if (ok) await databaseService.tloAuditLogs.create(buildTloAuditPayload(context.organizationId, "${e.audit}", "delete", \`${e.singular} deleted\`, id, "elevated"));\n        return ok;\n    }`;
    }).join("\n\n");
    return `import {\n    ${mapperImports.join(",\n    ")},\n} from "@/src/modules/database/lib/tenant-lifecycle-ops-mappers";\nimport { resolveOrganizationContext } from "@/src/modules/database/lib/organization-context";\nimport { databaseService } from "@/src/modules/database/services/database-service";\nimport { createAiOrchestrationClient } from "@/src/modules/ai-orchestration/sdk";\nimport { createKnowledgeClient } from "@/src/modules/knowledge/sdk";\nimport type {\n    ${typeImports.join(",\n    ")},\n} from "@/src/modules/tenant-lifecycle-ops/types";\n\nexport class TenantLifecycleOpsService {\n    private async getContext(authUserId: string, email: string, fullName?: string | null) {\n        return resolveOrganizationContext(authUserId, email, fullName);\n    }\n\n    private async getMaps(organizationId: string) {\n        const tenantContexts = await databaseService.tloTenantContexts.listByOrganization(organizationId);\n        return buildTenantContextLookupMaps(tenantContexts);\n    }\n\n    async getDashboardStats(authUserId: string, email: string, fullName?: string | null): Promise<TloDashboardStats> {\n        const context = await this.getContext(authUserId, email, fullName);\n        if (!context) return buildTloDashboardStats({ tenantContexts: [], lifecycleRecords: [], reactivationRequests: [], onboardingProgress: [], marketplaceModules: [], industryPacks: [], healthSnapshots: [], expansionOpportunities: [], auditLogs: [] });\n        const [tenantContexts, lifecycleRecords, reactivationRequests, onboardingProgress, marketplaceModules, industryPacks, healthSnapshots, expansionOpportunities, auditLogs] = await Promise.all([\n            this.getTenantContexts(authUserId, email, fullName),\n            this.getLifecycleRecords(authUserId, email, fullName),\n            this.getReactivationRequests(authUserId, email, fullName),\n            this.getOnboardingProgresses(authUserId, email, fullName),\n            this.getMarketplaceModules(authUserId, email, fullName),\n            this.getIndustryPacks(authUserId, email, fullName),\n            this.getHealthSnapshots(authUserId, email, fullName),\n            this.getExpansionOpportunities(authUserId, email, fullName),\n            this.getAuditLogs(authUserId, email, fullName),\n        ]);\n        return buildTloDashboardStats({ tenantContexts, lifecycleRecords, reactivationRequests, onboardingProgress, marketplaceModules, industryPacks, healthSnapshots, expansionOpportunities, auditLogs });\n    }\n\n    getPipelineInfo(): TloPipelineInfo {\n        return buildTloPipelineInfo();\n    }\n\n${methods}\n\n    async getAuditLogs(authUserId: string, email: string, fullName?: string | null): Promise<AuditEntry[]> {\n        const context = await this.getContext(authUserId, email, fullName);\n        if (!context) return [];\n        return (await databaseService.tloAuditLogs.listByOrganization(context.organizationId)).map(mapAuditEntry);\n    }\n\n    async getTenantContextOptions(authUserId: string, email: string, fullName?: string | null) {\n        const context = await this.getContext(authUserId, email, fullName);\n        if (!context) return [];\n        return (await databaseService.tloTenantContexts.listByOrganization(context.organizationId)).map((r) => ({ id: r.id, name: r.company_name }));\n    }\n\n    async sdkProvisionTenant(authUserId: string, email: string, input: TloSdkProvisionTenantInput, fullName?: string | null): Promise<TloSdkProvisionTenantResult> {\n        const ai = createAiOrchestrationClient(authUserId, email, fullName);\n        const knowledge = createKnowledgeClient(authUserId, email, fullName);\n        await knowledge.search({ query: input.companyName, limit: 5 });\n        const task = await ai.executeTask({ taskType: "provision_tenant", moduleSource: "tenant_lifecycle_ops", inputPayload: { contextKey: input.contextKey, companyName: input.companyName } });\n        const context = await this.createTenantContext(authUserId, email, { contextKey: input.contextKey, companyName: input.companyName, lifecycleStage: input.lifecycleStage ?? "lead" }, fullName);\n        const record = await this.createLifecycleRecord(authUserId, email, { tenantContextId: context.id, recordKey: \`\${input.contextKey}-lifecycle\`, currentStage: input.lifecycleStage ?? "lead" }, fullName);\n        return { contextId: context.id, contextKey: context.contextKey, recordId: record.id, aiTaskId: task?.taskId ?? null };\n    }\n\n    async sdkTransitionLifecycle(authUserId: string, email: string, input: TloSdkTransitionLifecycleInput, fullName?: string | null): Promise<TloSdkTransitionLifecycleResult> {\n        const ai = createAiOrchestrationClient(authUserId, email, fullName);\n        await ai.executeTask({ taskType: "transition_lifecycle", moduleSource: "tenant_lifecycle_ops", inputPayload: input });\n        const created = await this.createLifecycleTransition(authUserId, email, input, fullName);\n        return { transitionId: created.id, transitionKey: created.transitionKey, toStage: input.toStage, status: created.status };\n    }\n\n    async sdkInstallIndustryPack(authUserId: string, email: string, input: TloSdkInstallIndustryPackInput, fullName?: string | null): Promise<TloSdkInstallIndustryPackResult> {\n        const knowledge = createKnowledgeClient(authUserId, email, fullName);\n        await knowledge.search({ query: input.packName, limit: 3 });\n        const pack = await this.createIndustryPack(authUserId, email, { tenantContextId: input.tenantContextId, packKey: input.packKey, packName: input.packName, industry: input.industry ?? "technology" }, fullName);\n        const installation = await this.createPackInstallation(authUserId, email, { tenantContextId: input.tenantContextId, installationKey: \`\${input.packKey}-install\` }, fullName);\n        return { packId: pack.id, packKey: pack.packKey, installationId: installation.id, status: installation.status };\n    }\n}\n\nexport const tenantLifecycleOpsService = new TenantLifecycleOpsService();\n`;
}

function genHook() {
    const typeImports = [...new Set(entities.flatMap((e) => [e.input, e.summary]))].concat(["AuditEntry", "TloDashboardStats", "TloPipelineInfo"]).sort();
    const states = entities.map((e) => `    const [${e.state}, set${e.singular}s] = useState<${e.summary}[]>([]);`).join("\n");
    const setters = entities.map((e) => `        set${e.singular}s(result.${e.state}List);`).join("\n");
    const fetchItems = entities.map((e) => `            ${e.state}List,`).join("\n");
    const fetchCalls = entities.map((e) => `            tenantLifecycleOpsService.${e.get}(authUserId, email, fullName),`).join("\n");
    const returnItems = entities.map((e) => `        ${e.state},`).join("\n");
    const creates = entities.map((e) => `    const ${e.create} = useCallback(async (input: ${e.input}) => { if (!user) throw new Error("Authentication required"); await tenantLifecycleOpsService.${e.create}(user.id, user.email, input, user.fullName); await refresh(); }, [user, refresh]);`).join("\n");
    const returnCreates = entities.map((e) => `        ${e.create},`).join("\n");
    return `"use client";\n\nimport { useCallback, useEffect, useState } from "react";\nimport { useAuthStore } from "@/src/store/auth.store";\nimport { tenantLifecycleOpsService } from "@/src/modules/tenant-lifecycle-ops/services/tenant-lifecycle-ops.service";\nimport type {\n    ${typeImports.join(",\n    ")},\n} from "@/src/modules/tenant-lifecycle-ops/types";\n\nexport function useTenantLifecycleOps() {\n    const user = useAuthStore((state) => state.user);\n    const authUserId = user?.id;\n    const email = user?.email ?? "";\n    const fullName = user?.fullName;\n    const [loading, setLoading] = useState(true);\n    const [stats, setStats] = useState<TloDashboardStats | null>(null);\n    const [pipeline, setPipeline] = useState<TloPipelineInfo | null>(null);\n${states}\n    const [auditLogs, setAuditLogs] = useState<AuditEntry[]>([]);\n    const [tenantContextOptions, setTenantContextOptions] = useState<Array<{ id: string; name: string }>>([]);\n\n    const fetchData = useCallback(async () => {\n        if (!authUserId || !email) return { empty: true as const };\n        const [\n            statsData,\n            pipelineInfo,\n${fetchItems}\n            auditList,\n            tenantOpts,\n        ] = await Promise.all([\n            tenantLifecycleOpsService.getDashboardStats(authUserId, email, fullName),\n            Promise.resolve(tenantLifecycleOpsService.getPipelineInfo()),\n${fetchCalls}\n            tenantLifecycleOpsService.getAuditLogs(authUserId, email, fullName),\n            tenantLifecycleOpsService.getTenantContextOptions(authUserId, email, fullName),\n        ]);\n        return {\n            statsData,\n            pipelineInfo,\n${entities.map((e) => `            ${e.state}List,`).join("\n")}\n            auditList,\n            tenantOpts,\n        };\n    }, [authUserId, email, fullName]);\n\n    const applyData = useCallback((result: Awaited<ReturnType<typeof fetchData>>) => {\n        if ("empty" in result) { setLoading(false); return; }\n        setStats(result.statsData);\n        setPipeline(result.pipelineInfo);\n${setters}\n        setAuditLogs(result.auditList);\n        setTenantContextOptions(result.tenantOpts);\n        setLoading(false);\n    }, []);\n\n    const refresh = useCallback(async () => { applyData(await fetchData()); }, [fetchData, applyData]);\n\n    useEffect(() => {\n        let cancelled = false;\n        void fetchData().then((data) => { if (!cancelled) applyData(data); }).catch(() => { if (!cancelled) setLoading(false); });\n        return () => { cancelled = true; };\n    }, [fetchData, applyData]);\n\n${creates}\n\n    return {\n        loading,\n        stats,\n        pipeline,\n${returnItems}\n        auditLogs,\n        tenantContextOptions,\n        refresh,\n${returnCreates}\n    };\n}\n`;
}

function genField(f) {
    if (f.select) return `<select {...form.register("${f.name}")} className={inputClass}>{${f.select}.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}</select>`;
    if (f.number) return `<input type="number" step="any" {...form.register("${f.name}", { valueAsNumber: true })} placeholder="${f.placeholder}" className={inputClass} />`;
    return `<input {...form.register("${f.name}")} placeholder="${f.placeholder}" className={inputClass} />`;
}

function genPanels() {
    const schemaImports = entities.map((e) => e.schema).join(",\n    ");
    const formImports = entities.map((e) => `type ${e.form}`).join(",\n    ");
    const panels = entities.map((e) => {
        const defaults = e.orgScoped
            ? e.fields.map((f) => `${f.name}: ${f.number ? "0" : '""'}`).join(", ")
            : [`tenantContextId: ""`, ...e.fields.map((f) => `${f.name}: ${f.number ? "0" : '""'}`)].join(", ");
        const formFields = e.orgScoped
            ? e.fields.map((f) => `                ${genField(f)}`).join("\n")
            : `                <TenantContextSelect data={data} {...form.register("tenantContextId")} />\n${e.fields.map((f) => `                ${genField(f)}`).join("\n")}`;
        const listSub = e.maps ? `\${item.tenantContextName} • \${item.${e.keyField}}` : `\${item.${e.keyField}} • \${item.status}`;
        return `export function ${e.singular}sPanel({ data }: { data: TenantLifecycleOpsData }) {\n    const form = useForm<${e.form}>({ resolver: zodResolver(${e.schema}), defaultValues: { ${defaults} } });\n    return (\n        <div className="grid gap-6 xl:grid-cols-[1.4fr_1fr]">\n            <Card hover><SectionHeader title="${e.label}" description="Tenant lifecycle ${e.label.toLowerCase()}" /><div className="mt-6 space-y-3">\n                {data.${e.state}.length === 0 ? <EmptyState title="No ${e.label.toLowerCase()}" description="Create the first ${e.label.toLowerCase()} record." /> : data.${e.state}.map((item) => (\n                    <ListCard key={item.id} title={String(item.${e.titleKey})} subtitle={\`${listSub}\`} meta={\`\${item.status}\`} />\n                ))}\n            </div></Card>\n            <Card hover><SectionHeader title="Create ${e.label.toLowerCase().replace(/s$/, "")}" description="Add a new record" /><form className="mt-6 grid gap-4" onSubmit={form.handleSubmit(async (v) => data.${e.create}(v))}>\n${formFields}\n                <SaveButton loading={form.formState.isSubmitting} label="Create" />\n            </form></Card>\n        </div>\n    );\n}`;
    }).join("\n\n");
    return `"use client";\n\nimport { zodResolver } from "@hookform/resolvers/zod";\nimport { useForm } from "react-hook-form";\nimport { Card } from "@/src/components/ui/Card";\nimport { EmptyState } from "@/src/components/ui/EmptyState";\nimport { SectionHeader } from "@/src/components/ui/SectionHeader";\nimport { TLO_THEME, LIFECYCLE_STAGE_OPTIONS, INDUSTRY_PACK_OPTIONS, SEVERITY_OPTIONS } from "@/src/modules/tenant-lifecycle-ops/constants";\nimport type { useTenantLifecycleOps } from "@/src/modules/tenant-lifecycle-ops/hooks/useTenantLifecycleOps";\nimport {\n    ${schemaImports},\n    ${formImports},\n} from "@/src/modules/tenant-lifecycle-ops/schemas";\n\ntype TenantLifecycleOpsData = ReturnType<typeof useTenantLifecycleOps>;\nconst inputClass = "w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none ring-emerald-500/20 focus:ring-4 dark:border-slate-800 dark:bg-slate-950";\nfunction SaveButton({ loading, label = "Save changes" }: { loading?: boolean; label?: string }) {\n    return <button type="submit" disabled={loading} className="rounded-full bg-emerald-600 px-5 py-2.5 text-sm font-medium text-white transition hover:bg-emerald-500 disabled:opacity-60">{loading ? "Saving..." : label}</button>;\n}\nfunction ListCard({ title, subtitle, meta }: { title: string; subtitle: string; meta?: string }) {\n    return <div className="rounded-2xl border border-slate-200 px-4 py-3 dark:border-slate-800"><p className="font-medium">{title}</p><p className="text-sm text-slate-500">{subtitle}</p>{meta ? <p className="mt-1 text-xs text-emerald-600">{meta}</p> : null}</div>;\n}\nfunction TenantContextSelect({ data, ...props }: { data: TenantLifecycleOpsData } & React.SelectHTMLAttributes<HTMLSelectElement>) {\n    return <select {...props} className={inputClass}><option value="">Select tenant context</option>{data.tenantContextOptions.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}</select>;\n}\n\nexport function TenantLifecycleOpsOverviewPanel({ data }: { data: TenantLifecycleOpsData }) {\n    const pipeline = data.pipeline;\n    return (\n        <div className="grid gap-6 xl:grid-cols-2">\n            <Card hover><SectionHeader title="Tenant Lifecycle summary" description="Customer lifecycle, operations, onboarding, marketplace, health, and commercial growth" /><div className="mt-6 grid gap-3 sm:grid-cols-2">\n                <ListCard title="Tenant Contexts" subtitle={\`\${data.stats?.totalTenantContexts ?? 0} total\`} meta={\`\${data.stats?.activeTenantContexts ?? 0} active • \${data.stats?.lifecycleRecordCount ?? 0} lifecycle records\`} />\n                <ListCard title="Onboarding & Reactivation" subtitle={\`\${data.stats?.onboardingInProgressCount ?? 0} in progress\`} meta={\`\${data.stats?.openReactivationCount ?? 0} pending reactivations\`} />\n                <ListCard title="Marketplace & Packs" subtitle={\`\${data.stats?.marketplaceModuleCount ?? 0} modules\`} meta={\`\${data.stats?.industryPackCount ?? 0} industry packs\`} />\n                <ListCard title="Health & Growth" subtitle={\`\${(data.stats?.avgHealthScore ?? 0).toFixed(0)} avg health\`} meta={\`\${data.stats?.openExpansionCount ?? 0} expansion opportunities • \${data.stats?.auditCount ?? 0} audit entries\`} />\n            </div></Card>\n            <Card hover><SectionHeader title="Lifecycle pipeline" description={\`\${pipeline?.previousStage ?? "trial"} → \${pipeline?.currentStage ?? "onboarding"} → \${pipeline?.nextStage ?? "active"}\`} /><div className="mt-6 space-y-3">\n                {pipeline?.stages?.length ? pipeline.stages.map((stage) => (\n                    <ListCard key={stage.key} title={stage.label} subtitle={stage.key} meta={stage.label} />\n                )) : <EmptyState title="No pipeline data" description="Lifecycle pipeline stages will appear as tenant contexts progress." />}\n            </div></Card>\n        </div>\n    );\n}\n\n${panels}\n\nexport function TloAuditPanel({ data }: { data: TenantLifecycleOpsData }) {\n    return (\n        <Card hover><SectionHeader title="Tenant Lifecycle audit history" description="Security-first audit trail for lifecycle, operations, onboarding, and marketplace actions" /><div className="mt-6 space-y-3">\n            {data.auditLogs.length === 0 ? <EmptyState title="No audit entries" description="Audit logs are created automatically for tenant lifecycle operations." /> : data.auditLogs.map((entry) => (\n                <ListCard key={entry.id} title={entry.summary} subtitle={\`\${entry.entityType} • \${entry.action}\`} meta={\`\${entry.securityLevel} • \${new Date(entry.createdAt).toLocaleString()}\`} />\n            ))}\n        </div></Card>\n    );\n}\n\nexport function TenantLifecycleOpsSdkPanel({ data }: { data: TenantLifecycleOpsData }) {\n    return (\n        <Card hover><SectionHeader title="Shared Tenant Lifecycle Ops SDK" description="Import from @/src/modules/tenant-lifecycle-ops/sdk for tenant provisioning, lifecycle transitions, and industry pack installation" /><div className="mt-6 space-y-4 text-sm text-slate-600 dark:text-slate-300">\n            <ListCard title="createTenantLifecycleOpsClient()" subtitle="Factory for module-scoped Tenant Lifecycle Ops client with auth context" meta="Primary SDK for tenant lifecycle operations" />\n            <ListCard title="sdkProvisionTenant()" subtitle="Provision tenant context with lifecycle record and AI orchestration" meta="moduleSource: tenant_lifecycle_ops" />\n            <ListCard title="sdkTransitionLifecycle()" subtitle="Transition lifecycle stage with audit trail" meta="Lead → Trial → Onboarding → Active → Expansion → Renewal" />\n            <ListCard title="sdkInstallIndustryPack()" subtitle="Install industry pack with knowledge context" meta="Healthcare, financial services, retail, and more" />\n            <p className="text-xs text-slate-500">Theme: {TLO_THEME.primary} • Tenant contexts loaded: {data.tenantContexts.length}</p>\n            <pre className="overflow-x-auto rounded-2xl bg-slate-950 p-4 text-xs text-slate-100">{\`import { createTenantLifecycleOpsClient } from "@/src/modules/tenant-lifecycle-ops/sdk";\n\nconst tlo = createTenantLifecycleOpsClient(userId, email, fullName);\nawait tlo.provisionTenant({ contextKey: "acme", companyName: "Acme Corp" });\nawait tlo.transitionLifecycle({ tenantContextId, transitionKey: "t-001", fromStage: "trial", toStage: "onboarding" });\nawait tlo.installIndustryPack({ tenantContextId, packKey: "healthcare-v1", packName: "Healthcare Pack" });\`}</pre>\n        </div></Card>\n    );\n}\n`;
}

function genStats() {
    return `import { StatCard } from "@/src/components/ui/StatCard";\nimport type { TloDashboardStats } from "@/src/modules/tenant-lifecycle-ops/types";\n\ninterface TenantLifecycleOpsStatsProps { stats: TloDashboardStats | null; }\n\nexport function TenantLifecycleOpsStats({ stats }: TenantLifecycleOpsStatsProps) {\n    const cards = [\n        { title: "Tenant Contexts", value: String(stats?.totalTenantContexts ?? 0), detail: \`\${stats?.activeTenantContexts ?? 0} active • \${stats?.lifecycleRecordCount ?? 0} lifecycle records\`, trend: "up" as const },\n        { title: "Onboarding", value: String(stats?.onboardingInProgressCount ?? 0), detail: \`\${stats?.openReactivationCount ?? 0} pending reactivations • \${stats?.marketplaceModuleCount ?? 0} modules\`, trend: "up" as const },\n        { title: "Health Score", value: \`\${(stats?.avgHealthScore ?? 0).toFixed(0)}\`, detail: \`\${stats?.industryPackCount ?? 0} industry packs • \${stats?.openExpansionCount ?? 0} expansion ops\`, trend: "up" as const, tone: "accent" as const },\n        { title: "Audit Trail", value: String(stats?.auditCount ?? 0), detail: "Lifecycle, operations, onboarding, and marketplace audit entries", trend: "up" as const },\n    ];\n    return (\n        <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-4 [&_p:last-child]:text-emerald-600 dark:[&_p:last-child]:text-emerald-400">\n            {cards.map((card) => <StatCard key={card.title} title={card.title} value={card.value} detail={card.detail} trend={card.trend} tone={card.tone} />)}\n        </section>\n    );\n}\n`;
}

function genPage() {
    const panelImports = ["TenantLifecycleOpsOverviewPanel", ...entities.map((e) => `${e.singular}sPanel`), "TloAuditPanel", "TenantLifecycleOpsSdkPanel"];
    const tabs = [{ id: "TLO_TABS.overview", label: "Overview" }, ...entities.map((e) => ({ id: `TLO_TABS.${e.tab}`, label: e.label })), { id: "TLO_TABS.audit", label: "Audit" }, { id: "TLO_TABS.api", label: "SDK" }];
    const conditionals = [`{activeTab === TLO_TABS.overview ? <TenantLifecycleOpsOverviewPanel data={tenantLifecycleOps} /> : null}`, ...entities.map((e) => `{activeTab === TLO_TABS.${e.tab} ? <${e.singular}sPanel data={tenantLifecycleOps} /> : null}`), `{activeTab === TLO_TABS.audit ? <TloAuditPanel data={tenantLifecycleOps} /> : null}`, `{activeTab === TLO_TABS.api ? <TenantLifecycleOpsSdkPanel data={tenantLifecycleOps} /> : null}`];
    return `"use client";\n\nimport { motion } from "framer-motion";\nimport { useState } from "react";\nimport { LoadingState } from "@/src/components/ui/LoadingState";\nimport {\n    ${panelImports.join(",\n    ")},\n} from "@/src/modules/tenant-lifecycle-ops/components/TenantLifecycleOpsPanels";\nimport { TenantLifecycleOpsStats } from "@/src/modules/tenant-lifecycle-ops/components/TenantLifecycleOpsStats";\nimport { TLO_TABS } from "@/src/modules/tenant-lifecycle-ops/constants";\nimport { useTenantLifecycleOps } from "@/src/modules/tenant-lifecycle-ops/hooks/useTenantLifecycleOps";\n\nconst tabs = [\n    ${tabs.map((t) => `{ id: ${t.id}, label: "${t.label}" },`).join("\n    ")}\n] as const;\n\nexport function TenantLifecycleOpsPage() {\n    const tenantLifecycleOps = useTenantLifecycleOps();\n    const [activeTab, setActiveTab] = useState<(typeof TLO_TABS)[keyof typeof TLO_TABS]>(TLO_TABS.overview);\n\n    if (tenantLifecycleOps.loading) {\n        return <div className="mx-auto max-w-7xl"><LoadingState label="Loading Tenant Lifecycle" /></div>;\n    }\n\n    return (\n        <div className="mx-auto flex max-w-7xl flex-col gap-6 text-slate-900 dark:text-slate-100">\n            <motion.header initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="rounded-[2rem] border border-slate-200 bg-white/80 p-6 shadow-sm backdrop-blur dark:border-slate-800 dark:bg-slate-900/80">\n                <p className="text-sm font-medium uppercase tracking-[0.24em] text-emerald-600">V2 Program A Sprint 3</p>\n                <h1 className="mt-2 text-3xl font-semibold tracking-tight sm:text-4xl">Customer Lifecycle & Tenant Operations</h1>\n                <p className="mt-3 max-w-2xl text-sm text-slate-500 dark:text-slate-400">\n                    Customer lifecycle and tenant operations platform: lifecycle management, tenant operations, onboarding, marketplace modules, industry packs, health monitoring, customer success, commercial growth, security-first audit, and the shared Tenant Lifecycle Ops SDK. Pipeline: Lead → Trial → Onboarding → Active → Expansion → Renewal.\n                </p>\n            </motion.header>\n            <TenantLifecycleOpsStats stats={tenantLifecycleOps.stats} />\n            <div className="flex flex-wrap gap-2">\n                {tabs.map((tab) => (\n                    <button key={tab.id} type="button" onClick={() => setActiveTab(tab.id)} className={\`rounded-full px-4 py-2 text-sm font-medium transition \${activeTab === tab.id ? "bg-emerald-600 text-white" : "border border-slate-200 text-slate-600 hover:border-emerald-300 dark:border-slate-800 dark:text-slate-300"}\`}>{tab.label}</button>\n                ))}\n            </div>\n            ${conditionals.join("\n            ")}\n        </div>\n    );\n}\n`;
}

function genSdk() {
    return `import { tenantLifecycleOpsService } from "@/src/modules/tenant-lifecycle-ops/services/tenant-lifecycle-ops.service";\nimport type { TloSdkInstallIndustryPackInput, TloSdkProvisionTenantInput, TloSdkTransitionLifecycleInput } from "@/src/modules/tenant-lifecycle-ops/types";\n\nexport class TenantLifecycleOpsClient {\n    constructor(\n        private readonly authUserId: string,\n        private readonly email: string,\n        private readonly fullName?: string | null,\n    ) {}\n\n    async provisionTenant(input: TloSdkProvisionTenantInput) {\n        return tenantLifecycleOpsService.sdkProvisionTenant(this.authUserId, this.email, input, this.fullName);\n    }\n\n    async transitionLifecycle(input: TloSdkTransitionLifecycleInput) {\n        return tenantLifecycleOpsService.sdkTransitionLifecycle(this.authUserId, this.email, input, this.fullName);\n    }\n\n    async installIndustryPack(input: TloSdkInstallIndustryPackInput) {\n        return tenantLifecycleOpsService.sdkInstallIndustryPack(this.authUserId, this.email, input, this.fullName);\n    }\n\n    async getTenantContexts() {\n        return tenantLifecycleOpsService.getTenantContexts(this.authUserId, this.email, this.fullName);\n    }\n\n    async getDashboardStats() {\n        return tenantLifecycleOpsService.getDashboardStats(this.authUserId, this.email, this.fullName);\n    }\n\n    async getPipelineInfo() {\n        return tenantLifecycleOpsService.getPipelineInfo();\n    }\n}\n\nexport function createTenantLifecycleOpsClient(authUserId: string, email: string, fullName?: string | null): TenantLifecycleOpsClient {\n    return new TenantLifecycleOpsClient(authUserId, email, fullName);\n}\n\nexport { tenantLifecycleOpsService };\n`;
}

function genIndex() {
    return `export { TenantLifecycleOpsPage } from "@/src/modules/tenant-lifecycle-ops/components/TenantLifecycleOpsPage";\nexport { TenantLifecycleOpsStats } from "@/src/modules/tenant-lifecycle-ops/components/TenantLifecycleOpsStats";\nexport { tenantLifecycleOpsService } from "@/src/modules/tenant-lifecycle-ops/services/tenant-lifecycle-ops.service";\nexport { useTenantLifecycleOps } from "@/src/modules/tenant-lifecycle-ops/hooks/useTenantLifecycleOps";\nexport { createTenantLifecycleOpsClient, TenantLifecycleOpsClient } from "@/src/modules/tenant-lifecycle-ops/sdk";\nexport * from "@/src/modules/tenant-lifecycle-ops/types";\nexport * from "@/src/modules/tenant-lifecycle-ops/constants";\n`;
}

function genDataAccessPatch() {
    const imports = entities.map((e) => e.repo).concat(["TloAuditLogRepository"]).join(",\n    ");
    const props = entities.map((e) => `readonly ${e.db}: ${e.repo};`).concat(["readonly tloAuditLogs: TloAuditLogRepository;"]).join("\n    ");
    const inits = entities.map((e) => `this.${e.db} = new ${e.repo}();`).concat(["this.tloAuditLogs = new TloAuditLogRepository();"]).join("\n        ");
    return { imports, props, inits };
}

// write files
for (const dir of ["constants", "schemas", "services", "hooks", "components", "sdk", "types"]) {
    fs.mkdirSync(path.join(uiRoot, dir), { recursive: true });
}
fs.mkdirSync(path.dirname(dbTypesPath), { recursive: true });
fs.mkdirSync(path.dirname(reposPath), { recursive: true });
fs.mkdirSync(path.dirname(mappersPath), { recursive: true });

fs.writeFileSync(dbTypesPath, genDbTypes());
fs.writeFileSync(reposPath, genRepos());
fs.writeFileSync(path.join(uiRoot, "types/index.ts"), genTypes());
fs.writeFileSync(mappersPath, genMappers());
fs.writeFileSync(path.join(uiRoot, "constants/index.ts"), genConstants());
fs.writeFileSync(path.join(uiRoot, "schemas/index.ts"), `import { z } from "zod";\n\n${genSchemas()}`);
fs.writeFileSync(path.join(uiRoot, "services/tenant-lifecycle-ops.service.ts"), genService());
fs.writeFileSync(path.join(uiRoot, "hooks/useTenantLifecycleOps.ts"), genHook());
fs.writeFileSync(path.join(uiRoot, "components/TenantLifecycleOpsPanels.tsx"), genPanels());
fs.writeFileSync(path.join(uiRoot, "components/TenantLifecycleOpsStats.tsx"), genStats());
fs.writeFileSync(path.join(uiRoot, "components/TenantLifecycleOpsPage.tsx"), genPage());
fs.writeFileSync(path.join(uiRoot, "sdk/index.ts"), genSdk());
fs.writeFileSync(path.join(uiRoot, "index.ts"), genIndex());

const patch = genDataAccessPatch();
fs.writeFileSync(path.join(root, "scripts/.tlo-data-access-patch.json"), JSON.stringify(patch, null, 2));

console.log("Generated tenant-lifecycle-ops module");
console.log("Entity tabs:", entities.length);
console.log("Total tabs:", entities.length + 3);
